import { mergeProps } from '@base-ui/react/merge-props';
import { useRender } from '@base-ui/react/use-render';
import { cn } from '../../utils/cn';
import { aspectRatioVariants, type AspectRatioVariantProps } from './aspect-ratio.variants';

export interface AspectRatioProps extends Omit<useRender.ComponentProps<'div'>, 'className'> {
  className?: string;
  /** Width / height, e.g. `16 / 9` (default), `4 / 3`, `1`. */
  ratio?: number;
  /** Corner radius: none, md, lg (default) or xl. */
  radius?: AspectRatioVariantProps['radius'];
  /** Paints a bordered secondary placeholder behind the media (while it loads, or when empty). */
  surface?: boolean;
}

/** Fixed-ratio box for media: direct children (img, video, iframe, a placeholder) fill it. */
export function AspectRatio({ ratio = 16 / 9, radius, surface, className, style, render, ref, ...props }: AspectRatioProps) {
  return useRender({
    defaultTagName: 'div',
    render,
    ref,
    props: mergeProps<'div'>(props, {
      className: cn(aspectRatioVariants({ radius, surface }), className),
      style: { aspectRatio: String(ratio), ...style },
    }),
  });
}

import { tv, type VariantProps } from '../../utils/tv';

export const aspectRatioVariants = tv({
  base: 'relative w-full overflow-hidden *:absolute *:inset-0 *:size-full [&>img]:object-cover [&>video]:object-cover',
  variants: {
    radius: {
      none: 'rounded-none',
      md: 'rounded-md',
      lg: 'rounded-lg',
      xl: 'rounded-xl',
    },
    surface: {
      true: 'border border-border bg-secondary',
    },
  },
  defaultVariants: { radius: 'lg', surface: false },
});

export type AspectRatioVariantProps = VariantProps<typeof aspectRatioVariants>;

export { AspectRatio, type AspectRatioProps } from './AspectRatio';
export { aspectRatioVariants, type AspectRatioVariantProps } from './aspect-ratio.variants';
export { doc as aspectRatioDoc } from './AspectRatio.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'AspectRatio',
  group: 'Layout',
  status: 'stable',
  description:
    'A box locked to a width / height ratio (16:9 by default) for images, video and embeds; direct children fill it (object-cover). Radius none–xl and an optional bordered placeholder surface.',
  primitive: '@base-ui/react/use-render',
  tokens: ['border', 'secondary', 'muted-foreground', 'radius-lg'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
